def get_spec(strategy_id: str) -> Dict:
    return STRATEGY_SPECS.get(strategy_id.upper(), {})


def register_spec(strategy_id: str, spec: Dict) -> None:
    """Runtime registration of a spec (used by the Pine importer for user-submitted
    strategies) so the deterministic dossier generator can assemble their STEP 1."""
    STRATEGY_SPECS[strategy_id.upper()] = spec
